def tarif_tiket(umur, hari_libur):
    if umur < 0:
        raise ValueError("umur negatif")
    if umur < 5:
        return 0
    harga = 20000 if umur <= 12 else 35000
    if hari_libur:
        harga += 10000
    return harga

def jalankan(teks):
    match teks.split():
        case ["naik"]:
            return (0, 1)
        case ["turun"]:
            return (0, -1)
        case ["kiri"]:
            return (-1, 0)
        case ["kanan"]:
            return (1, 0)
        case ["lompat", n] if n.isdigit():
            return (0, int(n))
        case _:
            return None

