exercises.solution:
def early_stop(loss, kesabaran):
    terbaik = 0
    tanpa_perbaikan = 0
    for i in range(1, len(loss)):
        if loss[i] < loss[terbaik]:
            terbaik = i
            tanpa_perbaikan = 0
        else:
            tanpa_perbaikan += 1
            if tanpa_perbaikan >= kesabaran:
                break
    return terbaik

